def has_scopes(granted, required):
    # True, если токен покрывает все нужные области (учтите "действие:*" и "*")
    pass

solution:
def has_scopes(granted, required):
    def covered(scope):
        for g in granted:
            if g == "*" or g == scope:
                return True
            if g.endswith(":*") and scope.startswith(g[:-1]):
                return True
        return False

    return all(covered(scope) for scope in required)

